import type { ProjectContext } from './contracts';

export type VariantRunPlan =
  | { source: 'existing' }
  | { source: 'generated'; runtime: 'static' }
  | { source: 'generated'; runtime: 'app' };

export type RunTopology = 'code_gen' | 'static_preview';

export type RunProvision = 'git_worktree' | 'template_worktree' | 'none';

export type RunPreview = 'static_artifact' | 'dev_server';

export interface RunPlanPolicy {
  topology: RunTopology;
  provision: RunProvision;
  needsScaffoldBase: boolean;
  preview?: RunPreview;
}

export function resolveRunPlan(projectContext: ProjectContext): VariantRunPlan {
  if (projectContext.kind === 'existing') {
    return { source: 'existing' };
  }
  const runtime =
    projectContext.executionPlan?.mode === 'vite_app' ? 'app' : 'static';
  return { source: 'generated', runtime };
}

export function runPlanPolicy(plan: VariantRunPlan): RunPlanPolicy {
  if (plan.source === 'existing') {
    return {
      topology: 'code_gen',
      provision: 'git_worktree',
      needsScaffoldBase: false,
    };
  }
  if (plan.runtime === 'static') {
    return {
      topology: 'static_preview',
      provision: 'none',
      needsScaffoldBase: false,
      preview: 'static_artifact',
    };
  }
  return {
    topology: 'code_gen',
    provision: 'template_worktree',
    needsScaffoldBase: true,
    preview: 'dev_server',
  };
}

export function resolveRunPlanPolicy(
  projectContext: ProjectContext,
): RunPlanPolicy {
  return runPlanPolicy(resolveRunPlan(projectContext));
}
